INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9068, 'plPL', 'Tunika kruszyciela ziemi', 'Czy uczynisz mi ten zaszczyt i odzyskasz zbroje tych, którzy polegli w obronie tych ziem?$B$BZbroje zostały zbezczeszczone i bez wątpienia służą teraz złu, ale dzięki skrawkom pancerzy zniszczonych wojną można je odnowić, by znów posłużyły w bitwie.$B$BPrzynieś mi szczątki poległych wraz z materiałami do oczyszczenia, a rynsztunek kruszyciela ziemi będzie twój.$B$BPrzeszukaj Naxxramas.', 'Rimblat Kruszyciel Ziemi w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach wykona dla ciebie tunikę kruszyciela ziemi, jeśli przyniesiesz mu: 1× Zbezczeszczona tunika, 25× Skrawek kolczugi zniszczonej wojną, 4× Sztabka arkanitu i 3× Wyprawiona chropowata skóra.', '', 'Wróć do Rimblata Kruszyciela Ziemi przy Wieży Wschodniego Muru na Wschodnich Plagowiskach.', '', '', '', '', 0),
(9069, 'plPL', 'Osłony nóg kruszyciela ziemi', 'Czy uczynisz mi ten zaszczyt i odzyskasz zbroje tych, którzy polegli w obronie tych ziem?$B$BZbroje zostały zbezczeszczone i bez wątpienia służą teraz złu, ale dzięki skrawkom pancerzy zniszczonych wojną można je odnowić, by znów posłużyły w bitwie.$B$BPrzynieś mi szczątki poległych wraz z materiałami do oczyszczenia, a rynsztunek kruszyciela ziemi będzie twój.$B$BPrzeszukaj Naxxramas.', 'Rimblat Kruszyciel Ziemi w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach wykona dla ciebie osłony nóg kruszyciela ziemi, jeśli przyniesiesz mu: 1× Zbezczeszczone osłony nóg, 20× Skrawek kolczugi zniszczonej wojną, 3× Sztabka arkanitu i 5× Wyprawiona chropowata skóra.', '', 'Wróć do Rimblata Kruszyciela Ziemi przy Wieży Wschodniego Muru na Wschodnich Plagowiskach.', '', '', '', '', 0),
