(9079, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać hełm kościanej kosy.', 0),
(9080, 'plPL', '<Rohan ociera pot z czoła.>$B$BNad tymi naramiennikami trochę się napracowałem! Tylko nie daj się zabić jak jakiś żółtodziób, $N.', 0),
(9081, 'plPL', 'Zakłada się je na stopy. Słuchaj, chyba znowu nie $gwęszyłeś:węszyłaś; w Dłoni Tyra, co?', 0),
(9082, 'plPL', 'W razie absolutnej konieczności te rękawice mogłyby pewnie posłużyć za broń. Noś je z dumą!', 0),
(9083, 'plPL', 'Pas jest gotowy, $N. $GWidziałeś:Widziałaś; kiedyś tak dobrą rzecz sprzedaną tak tanio?', 0),
(9084, 'plPL', 'Karwasze są gotowe, $N.$B$B<Rohan kłania się.>', 0),
(9086, 'plPL', 'Twoja tunika wędrowca snów jest gotowa, $N.', 0),
(9087, 'plPL', 'Zgodnie z obietnicą: osłony nóg wędrowca snów.$B$B<Rayne podaje ci zbroję.>', 0),
(9088, 'plPL', 'Twoje nakrycie głowy wędrowca snów jest gotowe, $N.', 0),
(9089, 'plPL', 'Twoje naramienniki wędrowca snów są gotowe, $N.', 0),
(9090, 'plPL', 'Twoje buty wędrowca snów są gotowe, $N.', 0),
(9091, 'plPL', 'Twoje osłony dłoni wędrowca snów są gotowe, $N.', 0),
(9092, 'plPL', 'Twój pas wędrowca snów jest gotowy, $N.', 0),
(9093, 'plPL', 'Twoje osłony nadgarstków wędrowca snów są gotowe, $N.', 0),
(9095, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać szatę mroźnego ognia.', 0),
