(9111, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać szatę wiary.', 0),
(9112, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać nogawice wiary.', 0),
(9113, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać diadem wiary.', 0),
(9114, 'plPL', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9115, 'plPL', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9116, 'plPL', 'Szaty są gotowe, $N. Poraź swym prawym ogniem tych, którzy chcieliby skrzywdzić nasz świat.', 0),
(9117, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać pas wiary.', 0),
(9118, 'plPL', 'Doskonale, $N!$BMasz wszystko, czego potrzebuję, więc mogę teraz wykonać więzy wiary.', 0),
(9120, 'plPL', 'Przez wszystkie dni mojego życia nigdy bym się nie spodziewał, że to zobaczę...$b$b<Ojcu Montoyowi chyba cieknie ślinka.>$b$bO tak, zostaniesz $gnagrodzony, mój drogi:nagrodzona, moja droga;. Sowicie $gnagrodzony:nagrodzona;. Dawaj to. Już!', 0),
(9229, 'plPL', 'To jego pierścień! Ale zniszczony. Nie było żadnych innych śladów Ramaladniego?$B$B<Korfax krzywi się.>$B$BTo nie wróży Ramaladniemu dobrze. Ale pierścień... może da się go uratować.', 0),
(9230, 'plPL', 'Sam Ramaladni nie zrobiłby tego lepiej! Oto pierścień, jak obiecałem.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9049, 'plPL', 'Brakuje ci jeszcze kilku części. Idź i zdobądź wszystkie!', 0),
(9073, 'plPL', 'Czy $gprzyniosłeś:przyniosłaś; to, czego potrzebuję?', 0),
(9075, 'plPL', 'Czy $gprzyniosłeś:przyniosłaś; to, czego potrzebuję?', 0),
(9078, 'plPL', '<Rohan wybucha śmiechem.>$B$BWłaśnie dotarła do mnie ironia tego wszystkiego.', 0),
(9080, 'plPL', '<Rohan przygląda ci się podejrzliwie.>$B$B$GByłeś:Byłaś; ostatnio w Dłoni Tyra?', 0),
(9081, 'plPL', 'Po prostu przynieś mi materiały i przestań marnować mój czas.', 0),
(9082, 'plPL', 'Jak mam cokolwiek zrobić bez przedmiotów, o które prosiłem?', 0),
