INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15989, 3, 0, 'plPL', '%s wpada w szał!'),
(15990, 1, 0, 'plPL', 'Dobrze, że służycie mi tak wiernie. Wkrótce wszyscy będą służyć Królowi Liszowi, a na końcu zostaniecie nagrodzeni... o ile się nie zawahacie.'),
(15990, 3, 0, 'plPL', 'Wasze zabezpieczenia zawiodły! Natychmiast zajmijcie się tymi intruzami!'),
(15990, 6, 0, 'plPL', 'Kto śmie naruszać świętość mojej domeny? Strzeżcie się, każdy, kto tu wkracza, jest skazany na zgubę.'),
(15990, 15, 1, 'plPL', 'Dość! Mam już dosyć tych rozrywek!'),
(15990, 15, 2, 'plPL', 'Głupcy, za bardzo rozproszyliście swoje siły. Na wolność, moje sługi!'),
(16063, 1, 1, 'plPL', 'Może pójdą po rozum do głowy i uciekną, gdzie pieprz rośnie!'),
(16064, 1, 1, 'plPL', 'Dość się nasłuchałem twojego skamlenia. Zamknij jadaczkę, zanim ja ci ją zamknę!'),
(16065, 1, 0, 'plPL', 'Daj spokój, Zelieku, nie przepędzaj ich. Nie, zanim się z nimi zabawimy.'),
(30549, 1, 0, 'plPL', 'Dość tej paplaniny. Niech przyjdą! Zetrzemy ich kości na proch.'),
(30549, 1, 1, 'plPL', 'Zachowajcie gniew! Okiełznajcie wściekłość! Już wkrótce wszyscy będziecie mogli dać upust swojej frustracji.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12242, 'plPL', '%s wypatruje zombie do pożarcia!', '', 0),
(12348, 'plPL', '%s pożera wszystkie pobliskie zombie!', '', 0),
(12852, 'plPL', '', 'Wasze dawne życie, wasze śmiertelne pragnienia nic nie znaczą... jesteście teraz akolitami mistrza i będziecie służyć sprawie bez pytań! Największą chwałą jest umrzeć w służbie mistrza!', 0),
(12853, 'plPL', '', 'Mistrz mnie pomści!!', 0),
(12855, 'plPL', '', 'Żałosny nędzniku!', 0),
(12856, 'plPL', '', 'Zabijcie ich w imię mistrza!', 0),
(12857, 'plPL', '', 'Nie ukryjesz się przede mną!', 0),
(12858, 'plPL', '', 'Klęknij przede mną, robaku!', 0),
(12984, 'plPL', 'Kto śmie naruszać świętość mojej domeny? Strzeżcie się: każdy, kto tu wkracza, jest skazany na zgubę!', '', 0),
(12985, 'plPL', 'Głupcy! Myślicie, że zatriumfowaliście? Zbliżyliście się tylko o krok do otchłani!', '', 0),
(12986, 'plPL', 'Mam dość tych gier. Idźcie dalej, a skażę wasze dusze na niebyt!', '', 0),
(12987, 'plPL', 'Nie macie pojęcia, jakie okropności was czekają. Jeszcze nic nie widzieliście! Czeka na was zamarznięte serce Naxxramas!', '', 0),
(12988, 'plPL', 'Wkrótce wytępimy Przymierze i Hordę. Potem reszta Azeroth padnie przed potęgą mojej armii.', '', 0),
(12989, 'plPL', 'Najeźdźcy... tutaj?! ZNISZCZ ich, Kel\'Thuzadzie! Naxxramas nie może upaść!', '', 0),
(12990, 'plPL', 'Twoje siły są niemal gotowe, by uderzyć na twoich wrogów, mój panie.', '', 0),
(12991, 'plPL', 'Tak, mistrzu. Czas ich ostatecznej zagłady się zbliża... Co to?', '', 0),
(12992, 'plPL', 'Jak rozkażesz, mistrzu!', '', 0),
(12993, 'plPL', 'Chodźcie, bohaterowie... Z woli Króla Lisza zostaniecie zniszczeni.', '', 0),
(12994, 'plPL', 'Dobrze więc. Wojownicy zamarzniętych pustkowi, powstańcie! Rozkazuję wam walczyć, zabijać i umierać za waszego pana! Niech nikt nie przeżyje!', '', 0),
(12995, 'plPL', 'Módlcie się o litość!', '', 0),
(12996, 'plPL', 'Wykrzycz swój ostatni dech!', '', 0),
(12997, 'plPL', 'Nadszedł wasz koniec!', '', 0),
(12998, 'plPL', 'Mistrzu, potrzebuję pomocy!', '', 0),
(12999, 'plPL', 'Sługi, pachołkowie, żołnierze zimnego mroku! Usłuchajcie wezwania Kel\'Thuzada!', '', 0),
(13010, 'plPL', '', 'Broń się!', 0),
(13011, 'plPL', '', 'Touché...', 0),
(13013, 'plPL', '', 'Twoje życie należy do mnie!', 0),
(13014, 'plPL', '', 'Daj spokój, Zelieku, nie przepędzaj ich. Nie, zanim się z nimi zabawimy!', 0),
(13015, 'plPL', '', 'Mam nadzieję, że pożyją dość długo, żebym mogła się... przedstawić.', 0),
(13016, 'plPL', '', 'Pierwsze zabójstwo należy do mnie! Ktoś chce się założyć?', 0),
(13017, 'plPL', 'Twoja dusza jest teraz związana ze mną!', '', 0),
(13018, 'plPL', 'Nie ma ucieczki!', '', 0),
(13019, 'plPL', 'Aaargh! Nie... cieszcie... się! Wasze zwycięstwo jest puste, bo powrócę z mocą przekraczającą wasze wyobrażenia!', '', 0),
(13020, 'plPL', 'Zamrożę ci krew w żyłach!', '', 0),
(13021, 'plPL', 'Czeka cię mroczna pustka!', '', 0),
(13026, 'plPL', 'Jestem... pokonany.', '', 0),
(13028, 'plPL', 'Czekałem dość długo. Teraz staniesz przed żniwiarzem dusz.', '', 0),
(13030, 'plPL', 'W swej głupocie sami szukaliście zguby.', '', 0),
(13031, 'plPL', 'Zuchwale zlekceważyliście moce, których nie pojmujecie.', '', 0),
(13032, 'plPL', 'Ciężko walczyliście, by wedrzeć się do królestwa żniwiarza.', '', 0),
(13033, 'plPL', 'Teraz jest tylko jedno wyjście – kroczyć samotną ścieżką potępionych.', '', 0),
(13034, 'plPL', 'Dawaj, walcz, ty mały mazgaju!', '', 0),
(13035, 'plPL', 'Co za cholerne marnotrawstwo!', '', 0),
(13036, 'plPL', 'Następnym razem przyprowadź więcej kumpli!', '', 0),
(13037, 'plPL', 'Lubię mięsko dobrze przypieczone!', '', 0),
(13038, 'plPL', 'Do broni, obiboki! Mamy gości!', '', 0),
(13039, 'plPL', 'Dość się nasłuchałem twojego skamlenia! Zamknij jadaczkę, zanim ja ci ją zamknę!', '', 0),
(13040, 'plPL', 'Ale się ubawię, rozwalając te rozdziawione żonkile!', '', 0),
(13041, 'plPL', 'Teraz należysz do mnie.', '', 0),
(13043, 'plPL', 'Ty... jesteś następny.', '', 0),
(13044, 'plPL', '%s wydaje ostatnie tchnienie.', '', 0),
(13045, 'plPL', 'Zamknij oczy. Śpij.', '', 0),
(13046, 'plPL', 'Rasy tego świata zginą. To tylko kwestia czasu.', '', 0),
(13047, 'plPL', 'Widzę niekończące się cierpienie. Widzę męki. Widzę gniew. Widzę wszystko...', '', 0),
(13048, 'plPL', 'Wkrótce świat zadrży.', '', 0),
(13049, 'plPL', 'Nadszedł wasz koniec.', '', 0),
(13050, 'plPL', 'Głodne robaki będą ucztować na waszym gnijącym ciele.', '', 0),
(13051, 'plPL', 'Szukasz śmierci?', '', 0),
(13053, 'plPL', 'Nie ruszaj się!', '', 0),
(13055, 'plPL', 'Nie zaznasz spokoju w śmierci.', '', 0),
(13056, 'plPL', 'Wola mistrza się dokonała.', '', 0),
(13057, 'plPL', 'Pokłońcie się potędze Plagi!', '', 0),
(13058, 'plPL', 'Dość tej paplaniny. Niech przyjdą. Zetrzemy ich kości na proch.', '', 0),
(13059, 'plPL', 'Zachowajcie gniew. Okiełznajcie wściekłość. Już wkrótce wszyscy będziecie mogli dać upust swojej frustracji.', '', 0),
(13060, 'plPL', 'Życie nie ma znaczenia. To w śmierci przechodzimy prawdziwą próbę.', '', 0),
(13086, 'plPL', 'Zabić...', '', 0),
(13087, 'plPL', 'Zjeść... twoje... kości...', '', 0),
(13088, 'plPL', 'Złamać... cię!!', '', 0),
(13090, 'plPL', 'Teraz poczujesz ból...', '', 0),
(13091, 'plPL', 'Za późno!! Muszę... być... posłuszny!!', '', 0),
(13092, 'plPL', 'Szybko! Pro-o-oszę, szybko!!', '', 0),
(13093, 'plPL', 'Prze-e-estań! Niech to się skończy!!', '', 0),
(13094, 'plPL', 'Pomóżcie mi! Ratujcie!', '', 0),
(13095, 'plPL', 'Nie-e-e-e!!', '', 0),
(13096, 'plPL', 'Ty... teraz zginąć!!', '', 0),
(13097, 'plPL', 'Uciekajcie, póki nie jest za późno!', '', 0),
(13098, 'plPL', 'Tak... powinno być.', '', 0),
(13099, 'plPL', 'Wybaczcie mi.', '', 0),
(13100, 'plPL', 'Nie mam wyboru, muszę być posłuszny!', '', 0),
(13101, 'plPL', 'Najeźdźcy, natychmiast zaniechajcie tej głupiej wyprawy! Zawróćcie, póki jeszcze możecie!', '', 0),
(13102, 'plPL', 'Może pójdą po rozum do głowy... i uciekną, gdzie pieprz rośnie.', '', 0),
(13103, 'plPL', 'Nie idźcie dalej! Zawróćcie, póki jeszcze jest czas!', '', 0),
(13150, 'plPL', 'Nie!!! Przeklinam was, intruzi! Armie Króla Lisza was dopadną. Nie uciekniecie przed swoim losem...', '', 0),
(13492, 'plPL', 'Wasze marne czary są niczym wobec potęgi Plagi!', '', 0),
(18258, 'plPL', 'Teraz należysz do mnie.', '', 0),
(27382, 'plPL', 'Nie macie pojęcia, jakie okropności was czekają. Jeszcze nic nie widzieliście! Czeka na was zamarznięte serce Naxxramas!', '', 0),
(29805, 'plPL', '%s rechocze jak szaleniec.', '', 0),
(31019, 'plPL', '', '%s jest pod wpływem Objęć wdowy!', 0),
(32303, 'plPL', '', '%s owija swoją ofiarę siecią w kokon!', 0),
(32304, 'plPL', '', '%s rozpyla wszędzie nici pajęczyny!', 0),
(32305, 'plPL', '', 'Na sieci pojawiają się pajączki!', 0),
(32306, 'plPL', '%s teleportuje się w wir walki!', '', 0),
(32307, 'plPL', 'Brama środkowa się otwiera!', '', 0),
(32318, 'plPL', '%s rozpryskuje szlam po całej komnacie!', '', 0),
(32321, 'plPL', '%s dziesiątkuje wszystkie pobliskie ciała!', '', 0),
(32324, 'plPL', 'Polaryzacja się zmieniła!', '', 0),
(32332, 'plPL', '%s teleportuje się i zaczyna splatać zaklęcie!', '', 0),
(32333, 'plPL', '%s znów rusza do ataku!', '', 0),
(32334, 'plPL', 'Aura nekrotycznej energii blokuje wszelkie leczenie!', '', 0),
(32335, 'plPL', 'Aura zanika – leczenie znów jest możliwe!', '', 0),
(32801, 'plPL', 'Szafiron wzbija się w powietrze!', '', 0),
(32802, 'plPL', 'Szafiron wznawia ataki!', '', 0),
(32803, 'plPL', 'Kel\'Thuzad atakuje!', '', 0),
(32805, 'plPL', 'Moc aury zaczyna słabnąć!', '', 0),
(33087, 'plPL', '', '%s rzuca Nieustępliwy ból na wszystkich!', 0),
(33088, 'plPL', '%s rzuca Potępienie na wszystkich!', '', 0),
(33116, 'plPL', 'Śmierć... mnie nie powstrzyma.', '', 0),
(34133, 'plPL', 'Nikt nie przejdzie!', '', 0),
(35747, 'plPL', 'Dostaniesz swoje wyzwanie, Fordringu.', '', 0),
(35749, 'plPL', 'Dusze twoich poległych czempionów będą moje, Fordringu.', '', 0),
(39601, 'plPL', 'Dzię... kuję...', '', 0),
(61582, 'plPL', 'Uciekajcie, póki jeszcze możecie!', 'Uciekajcie, póki jeszcze możecie!', 0),
(73351, 'plPL', 'Widzę cię!', 'Widzę cię!', 0);
